CREATE TABLE IF NOT EXISTS users(username varchar(64) PRIMARY KEY,salt varchar(128) NOT NULL,password_hash varchar(64) NOT NULL,role varchar(16) NOT NULL CHECK(role IN ('admin','viewer')));
CREATE TABLE IF NOT EXISTS sessions(token varchar(64) PRIMARY KEY,username varchar(64) REFERENCES users(username),expires timestamp with time zone NOT NULL);
CREATE TABLE IF NOT EXISTS nodes(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name varchar(255) NOT NULL UNIQUE,url varchar(2048) NOT NULL,token text NOT NULL,last_seen timestamp with time zone);
CREATE TABLE IF NOT EXISTS entries(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name varchar(255) NOT NULL,url varchar(2048) NOT NULL,project varchar(255) NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS audit(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor varchar(255) NOT NULL,action varchar(255) NOT NULL,target text NOT NULL,outcome text NOT NULL,created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS audit_login_window ON audit(actor,action,created_at);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires);
CREATE TABLE IF NOT EXISTS installation_cache(node_id bigint NOT NULL REFERENCES nodes(id),job_id varchar(32) NOT NULL,status varchar(40) NOT NULL,public_json text NOT NULL,updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(node_id,job_id));
CREATE TABLE IF NOT EXISTS service_checks(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name varchar(128) NOT NULL,cluster_name varchar(128) NOT NULL DEFAULT '',kind varchar(40) NOT NULL,url varchar(2048) NOT NULL,expected_status int NOT NULL DEFAULT 200,enabled boolean NOT NULL DEFAULT TRUE,status varchar(24) NOT NULL DEFAULT 'UNKNOWN',message varchar(2048),latency_ms bigint,checked_at timestamp with time zone);
CREATE TABLE IF NOT EXISTS service_alerts(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,service_id bigint NOT NULL REFERENCES service_checks(id),status varchar(24) NOT NULL,message varchar(2048),created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS platform_settings(setting_key varchar(128) PRIMARY KEY,setting_value varchar(8192) NOT NULL,revision bigint NOT NULL DEFAULT 1,updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS deployment_drafts(id varchar(64) PRIMARY KEY,actor varchar(64) NOT NULL,name varchar(128) NOT NULL,content text NOT NULL,updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP);
